    fat: num(/(?:^|[^a-z])fat\W{0,3}(\d+(?:\.\d+)?)/i),
    carbs: num(/carb(?:ohydrate)?s?\W{0,3}(\d+(?:\.\d+)?)/i),
    fibre: num(/fib(?:re|er)\W{0,3}(\d+(?:\.\d+)?)/i),
    sugar: num(/sugar\W{0,3}(\d+(?:\.\d+)?)/i)
