    title: title || 'Untitled recipe',
    ingredients: ings,
    steps,
    servings,
    yield: yieldTxt,
    servingSize,
    notes,
    prepMinutes: prep,
    cookMinutes: cook,
    image,
    category: grab(/course\W{0,3}([a-z &,-]{3,30})/i),
    cuisine: grab(/cuisine\W{0,3}([a-z &,-]{3,30})/i),
